        
namespace MAVLinkSharp.Bindings {

    /// <summary>
    /// Commands to be executed by the MAV. They can be executed on user request, or as part of a mission script. If the action is used in a mission, the parameter mapping to the waypoint/mission message is as follows: Param 1, Param 2, Param 3, Param 4, X: Param 5, Y:Param 6, Z:Param 7. This command list is similar what ARINC 424 is for commercial aircraft: A data format how to interpret waypoint/mission data. NaN and INT32_MAX may be used in float/integer params (respectively) to indicate optional/default values (e.g. to use the component's current yaw or latitude rather than a specific value). See https://mavlink.io/en/guide/xml_schema.html#MAV_CMD for information about the structure of the MAV_CMD entries
    /// </summary>    
    public enum MAVCmdFlags {
        NavWaypoint                                = 16,          //[Params 0: Hold               | 1: AcceptRadius       | 2: PassRadius         | 3: Yaw                | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Navigate to waypoint. This is intended for use in missions (for guided commands outside of missions use MAV_CMD_DO_REPOSITION).
        NavLoiterUnlim                             = 17,          //[Params 2: Radius             | 3: Yaw                | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Loiter around this waypoint an unlimited amount of time
        NavLoiterTurns                             = 18,          //[Params 0: Turns              | 1: HeadingRequired    | 2: Radius             | 3: XtrackLocation     | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Loiter around this waypoint for X turns
        NavLoiterTime                              = 19,          //[Params 0: Time               | 1: HeadingRequired    | 2: Radius             | 3: XtrackLocation     | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Loiter at the specified latitude, longitude and altitude for a certain amount of time. Multicopter vehicles stop at the point (within a vehicle-specific acceptance radius). Forward-only moving vehicles (e.g. fixed-wing) circle the point with the specified radius/direction. If the Heading Required parameter (2) is non-zero forward moving aircraft will only leave the loiter circle once heading towards the next waypoint.
        NavReturnToLaunch                          = 20,          //Return to launch location
        NavLand                                    = 21,          //[Params 0: AbortAlt           | 1: LandMode           | 3: YawAngle           | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Land at location.
        NavTakeoff                                 = 22,          //[Params 0: Pitch              | 3: Yaw                | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Takeoff from ground / hand. Vehicles that support multiple takeoff modes (e.g. VTOL quadplane) should take off using the currently configured mode.
        NavLandLocal                               = 23,          //[Params 0: Target             | 1: Offset             | 2: DescendRate        | 3: Yaw                | 4: YPosition          | 5: XPosition          | 6: ZPosition         ] Land at local position (local frame only)
        NavTakeoffLocal                            = 24,          //[Params 0: Pitch              | 2: AscendRate         | 3: Yaw                | 4: YPosition          | 5: XPosition          | 6: ZPosition         ] Takeoff from local position (local frame only)
        NavFollow                                  = 25,          //[Params 0: Following          | 1: GroundSpeed        | 2: Radius             | 3: Yaw                | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Vehicle following, i.e. this waypoint represents the position of a moving vehicle
        NavContinueAndChangeAlt                    = 30,          //[Params 0: Action             | 6: Altitude          ] Continue on the current course and climb/descend to specified altitude.  When the altitude is reached continue to the next command (i.e., don't proceed to the next command until the desired altitude is reached.
        NavLoiterToAlt                             = 31,          //[Params 0: HeadingRequired    | 1: Radius             | 3: XtrackLocation     | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Begin loiter at the specified Latitude and Longitude.  If Lat=Lon=0, then loiter at the current position.  Don't consider the navigation command complete (don't leave loiter) until the altitude has been reached. Additionally, if the Heading Required parameter is non-zero the aircraft will not leave the loiter until heading toward the next waypoint.
        DoFollow                                   = 32,          //[Params 0: SystemID           | 3: AltitudeMode       | 4: Altitude           | 6: TimetoLand        ] Begin following a target
        DoFollowReposition                         = 33,          //[Params 0: CameraQ1           | 1: CameraQ2           | 2: CameraQ3           | 3: CameraQ4           | 4: AltitudeOffset     | 5: XOffset            | 6: YOffset           ] Reposition the MAV after a follow target command has been sent
        DoOrbit                                    = 34,          //[Params 0: Radius             | 1: Velocity           | 2: YawBehavior        | 3: Orbits             | 4: Latitude/X         | 5: Longitude/Y        | 6: Altitude/Z        ] Start orbiting on the circumference of a circle defined by the parameters. Setting values to NaN/INT32_MAX (as appropriate) results in using defaults.
        DoFigureEight                              = 35,          //[Params 0: MajorRadius        | 1: MinorRadius        | 3: Orientation        | 4: Latitude/X         | 5: Longitude/Y        | 6: Altitude/Z        ] Fly a figure eight path as defined by the parameters. | Set parameters to NaN/INT32_MAX (as appropriate) to use system-default values. | The command is intended for fixed wing vehicles (and VTOL hybrids flying in fixed-wing mode), allowing POI tracking for gimbals that don't support infinite rotation. | This command only defines the flight path. Speed should be set independently (use e.g. MAV_CMD_DO_CHANGE_SPEED). | Yaw and other degrees of freedom are not specified, and will be flight-stack specific (on vehicles where they can be controlled independent of the heading).
        NavRoi                                     = 80,          //[Params 0: ROIMode            | 1: WPIndex            | 2: ROIIndex           | 4: X                  | 5: Y                  | 6: Z                 ] Sets the region of interest (ROI) for a sensor set or the vehicle itself. This can then be used by the vehicle's control system to control the vehicle attitude and the attitude of various sensors such as cameras.
        NavPathplanning                            = 81,          //[Params 0: LocalCtrl          | 1: GlobalCtrl         | 3: Yaw                | 4: Latitude/X         | 5: Longitude/Y        | 6: Altitude/Z        ] Control autonomous path planning on the MAV.
        NavSplineWaypoint                          = 82,          //[Params 0: Hold               | 4: Latitude/X         | 5: Longitude/Y        | 6: Altitude/Z        ] Navigate to waypoint using a spline path.
        NavVtolTakeoff                             = 84,          //[Params 1: TransitionHeading  | 3: YawAngle           | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Takeoff from ground using VTOL mode, and transition to forward flight with specified heading. The command should be ignored by vehicles that dont support both VTOL and fixed-wing flight (multicopters, boats,etc.).
        NavVtolLand                                = 85,          //[Params 0: LandOptions        | 2: ApproachAltitude   | 3: Yaw                | 4: Latitude           | 5: Longitude          | 6: GroundAltitude    ] Land using VTOL mode
        NavGuidedEnable                            = 92,          //[Params 0: Enable            ] Hand control over to an external controller
        NavDelay                                   = 93,          //[Params 0: Delay              | 1: Hour               | 2: Minute             | 3: Second            ] Delay the next navigation command a number of seconds or until a specified time
        NavPayloadPlace                            = 94,          //[Params 0: MaxDescent         | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Descend and place payload. Vehicle moves to specified location, descends until it detects a hanging payload has reached the ground, and then releases the payload. If ground is not detected before the reaching the maximum descent value (param1), the command will complete without releasing the payload.
        NavLast                                    = 95,          //NOP - This command is only used to mark the upper limit of the NAV/ACTION commands in the enumeration
        ConditionDelay                             = 112,         //[Params 0: Delay             ] Delay mission state machine.
        ConditionChangeAlt                         = 113,         //[Params 0: Rate               | 6: Altitude          ] Ascend/descend to target altitude at specified rate. Delay mission state machine until desired altitude reached.
        ConditionDistance                          = 114,         //[Params 0: Distance          ] Delay mission state machine until within desired distance of next NAV point.
        ConditionYaw                               = 115,         //[Params 0: Angle              | 1: AngularSpeed       | 2: Direction          | 3: Relative          ] Reach a certain target angle.
        ConditionLast                              = 159,         //NOP - This command is only used to mark the upper limit of the CONDITION commands in the enumeration
        DoSetMode                                  = 176,         //[Params 0: Mode               | 1: CustomMode         | 2: CustomSubmode     ] Set system mode.
        DoJump                                     = 177,         //[Params 0: Number             | 1: Repeat            ] Jump to the desired command in the mission list.  Repeat this action only the specified number of times
        DoChangeSpeed                              = 178,         //[Params 0: SpeedType          | 1: Speed              | 2: Throttle          ] Change speed and/or throttle set points. The value persists until it is overridden or there is a mode change
        DoSetHome                                  = 179,         //[Params 0: UseCurrent         | 1: Roll               | 2: Pitch              | 3: Yaw                | 4: Latitude           | 5: Longitude          | 6: Altitude          ] | Sets the home position to either to the current position or a specified position. | The home position is the default position that the system will return to and land on. | The position is set automatically by the system during the takeoff (and may also be set using this command). | Note: the current home position may be emitted in a HOME_POSITION message on request (using MAV_CMD_REQUEST_MESSAGE with param1=242).
        DoSetParameter                             = 180,         //[Params 0: Number             | 1: Value             ] Set a system parameter.  Caution!  Use of this command requires knowledge of the numeric enumeration value of the parameter.
        DoSetRelay                                 = 181,         //[Params 0: Instance           | 1: Setting           ] Set a relay to a condition.
        DoRepeatRelay                              = 182,         //[Params 0: Instance           | 1: Count              | 2: Time              ] Cycle a relay on and off for a desired number of cycles with a desired period.
        DoSetServo                                 = 183,         //[Params 0: Instance           | 1: PWM               ] Set a servo to a desired PWM value.
        DoRepeatServo                              = 184,         //[Params 0: Instance           | 1: PWM                | 2: Count              | 3: Time              ] Cycle a between its nominal setting and a desired PWM for a desired number of cycles with a desired period.
        DoFlighttermination                        = 185,         //[Params 0: Terminate         ] Terminate flight immediately. | Flight termination immediately and irreversibly terminates the current flight, returning the vehicle to ground. | The vehicle will ignore RC or other input until it has been power-cycled. | Termination may trigger safety measures, including: disabling motors and deployment of parachute on multicopters, and setting flight surfaces to initiate a landing pattern on fixed-wing). | On multicopters without a parachute it may trigger a crash landing. | Support for this command can be tested using the protocol bit: MAV_PROTOCOL_CAPABILITY_FLIGHT_TERMINATION. | Support for this command can also be tested by sending the command with param1=0 (< 0.5); the ACK should be either MAV_RESULT_FAILED or MAV_RESULT_UNSUPPORTED.
        DoChangeAltitude                           = 186,         //[Params 0: Altitude           | 1: Frame             ] Change altitude set point.
        DoSetActuator                              = 187,         //[Params 0: Actuator1          | 1: Actuator2          | 2: Actuator3          | 3: Actuator4          | 4: Actuator5          | 5: Actuator6          | 6: Index             ] Sets actuators (e.g. servos) to a desired value. The actuator numbers are mapped to specific outputs (e.g. on any MAIN or AUX PWM or UAVCAN) using a flight-stack specific mechanism (i.e. a parameter).
        DoReturnPathStart                          = 188,         //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] Mission item to specify the start of a failsafe/landing return-path segment (the end of the segment is the next MAV_CMD_DO_LAND_START item). | A vehicle that is using missions for landing (e.g. in a return mode) will join the mission on the closest path of the return-path segment (instead of MAV_CMD_DO_LAND_START or the nearest waypoint). | The main use case is to minimize the failsafe flight path in corridor missions, where the inbound/outbound paths are constrained (by geofences) to the same particular path. | The MAV_CMD_NAV_RETURN_PATH_START would be placed at the start of the return path. | If a failsafe occurs on the outbound path the vehicle will move to the nearest point on the return path (which is parallel for this kind of mission), effectively turning round and following the shortest path to landing. | If a failsafe occurs on the inbound path the vehicle is already on the return segment and will continue to landing. | The Latitude/Longitude/Altitude are optional, and may be set to 0 if not needed. | If specified, the item defines the waypoint at which the return segment starts. | If sent using as a command, the vehicle will perform a mission landing (using the land segment if defined) or reject the command if mission landings are not supported, or no mission landing is defined. When used as a command any position information in the command is ignored.
        DoLandStart                                = 189,         //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] Mission item to mark the start of a mission landing pattern, or a command to land with a mission landing pattern. | When used in a mission, this is a marker for the start of a sequence of mission items that represent a landing pattern. | It should be followed by a navigation item that defines the first waypoint of the landing sequence. | The start marker positional params are used only for selecting what landing pattern to use if several are defined in the mission (the selected pattern will be the one with the marker position that is closest to the vehicle when a landing is commanded). | If the marker item position has zero-values for latitude, longitude, and altitude, then landing pattern selection is instead based on the position of the first waypoint in the landing sequence. | When sent as a command it triggers a landing using a mission landing pattern. | The location parameters are not used in this case, and should be set to 0.
        DoRallyLand                                = 190,         //[Params 0: Altitude           | 1: Speed             ] Mission command to perform a landing from a rally point.
        DoGoAround                                 = 191,         //[Params 0: Altitude          ] Mission command to safely abort an autonomous landing.
        DoReposition                               = 192,         //[Params 0: Speed              | 1: Bitmask            | 2: Radius             | 3: Yaw                | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Reposition the vehicle to a specific WGS84 global position. This command is intended for guided commands (for missions use MAV_CMD_NAV_WAYPOINT instead).
        DoPauseContinue                            = 193,         //[Params 0: Continue          ] If in a GPS controlled position mode, hold the current position or continue.
        DoSetReverse                               = 194,         //[Params 0: Reverse           ] Set moving direction to forward or reverse.
        DoSetRoiLocation                           = 195,         //[Params 0: GimbaldeviceID     | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Sets the region of interest (ROI) to a location. This can then be used by the vehicle's control system to control the vehicle attitude and the attitude of various sensors such as cameras. This command can be sent to a gimbal manager but not to a gimbal device. A gimbal is not to react to this message.
        DoSetRoiWpnextOffset                       = 196,         //[Params 0: GimbaldeviceID     | 4: PitchOffset        | 5: RollOffset         | 6: YawOffset         ] Sets the region of interest (ROI) to be toward next waypoint, with optional pitch/roll/yaw offset. This can then be used by the vehicle's control system to control the vehicle attitude and the attitude of various sensors such as cameras. This command can be sent to a gimbal manager but not to a gimbal device. A gimbal device is not to react to this message.
        DoSetRoiNone                               = 197,         //[Params 0: GimbaldeviceID    ] Cancels any previous ROI command returning the vehicle/sensors to default flight characteristics. This can then be used by the vehicle's control system to control the vehicle attitude and the attitude of various sensors such as cameras. This command can be sent to a gimbal manager but not to a gimbal device. A gimbal device is not to react to this message. After this command the gimbal manager should go back to manual input if available, and otherwise assume a neutral position.
        DoSetRoiSysid                              = 198,         //[Params 0: SystemID           | 1: GimbaldeviceID    ] Mount tracks system with specified system ID. Determination of target vehicle position may be done with GLOBAL_POSITION_INT or any other means. This command can be sent to a gimbal manager but not to a gimbal device. A gimbal device is not to react to this message.
        DoControlVideo                             = 200,         //[Params 0: ID                 | 1: Transmission       | 2: Interval           | 3: Recording         ] Control onboard camera system.
        DoSetRoi                                   = 201,         //[Params 0: ROIMode            | 1: WPIndex            | 2: ROIIndex          ] Sets the region of interest (ROI) for a sensor set or the vehicle itself. This can then be used by the vehicle's control system to control the vehicle attitude and the attitude of various sensors such as cameras.
        DoDigicamConfigure                         = 202,         //[Params 0: Mode               | 1: ShutterSpeed       | 2: Aperture           | 3: ISO                | 4: Exposure           | 5: CommandIdentity    | 6: EngineCut-off     ] Configure digital camera. This is a fallback message for systems that have not yet implemented PARAM_EXT_XXX messages and camera definition files (see https://mavlink.io/en/services/camera_def.html ).
        DoDigicamControl                           = 203,         //[Params 0: SessionControl     | 1: ZoomAbsolute       | 2: ZoomRelative       | 3: Focus              | 4: ShootCommand       | 5: CommandIdentity    | 6: ShotID            ] Control digital camera. This is a fallback message for systems that have not yet implemented PARAM_EXT_XXX messages and camera definition files (see https://mavlink.io/en/services/camera_def.html ).
        DoMountConfigure                           = 204,         //[Params 0: Mode               | 1: StabilizeRoll      | 2: StabilizePitch     | 3: StabilizeYaw       | 4: RollInputMode      | 5: PitchInputMode     | 6: YawInputMode      ] Mission command to configure a camera or antenna mount
        DoMountControl                             = 205,         //[Params 0: Pitch              | 1: Roll               | 2: Yaw                | 3: Altitude           | 4: Latitude           | 5: Longitude          | 6: Mode              ] Mission command to control a camera or antenna mount
        DoSetCamTriggDist                          = 206,         //[Params 0: Distance           | 1: Shutter            | 2: Trigger            | 3: TargetCameraID    ] Mission command to set camera trigger distance for this flight. The camera is triggered each time this distance is exceeded. This command can also be used to set the shutter integration time for the camera.
        DoFenceEnable                              = 207,         //[Params 0: Enable             | 1: Types             ] | Enable the geofence. | This can be used in a mission or via the command protocol. | The persistence/lifetime of the setting is undefined. | Depending on flight stack implementation it may persist until superseded, or it may revert to a system default at the end of a mission. | Flight stacks typically reset the setting to system defaults on reboot.
        DoParachute                                = 208,         //[Params 0: Action            ] Mission item/command to release a parachute or enable/disable auto release.
        DoMotorTest                                = 209,         //[Params 0: Instance           | 1: ThrottleType       | 2: Throttle           | 3: Timeout            | 4: MotorCount         | 5: TestOrder         ] Command to perform motor test.
        DoInvertedFlight                           = 210,         //[Params 0: Inverted          ] Change to/from inverted flight.
        DoGripper                                  = 211,         //[Params 0: GripperID          | 1: Action            ] Mission command to operate a gripper.
        DoAutotuneEnable                           = 212,         //[Params 0: Enable             | 1: Axis              ] Enable/disable autotune.
        NavSetYawSpeed                             = 213,         //[Params 0: Yaw                | 1: Speed              | 2: Angle             ] Sets a desired vehicle turn angle and speed change.
        DoSetCamTriggInterval                      = 214,         //[Params 0: TriggerCycle       | 1: ShutterIntegration | 2: TargetCameraID    ] Mission command to set camera trigger interval for this flight. If triggering is enabled, the camera is triggered each time this interval expires. This command can also be used to set the shutter integration time for the camera.
        DoMountControlQuat                         = 220,         //[Params 0: Q1                 | 1: Q2                 | 2: Q3                 | 3: Q4                ] Mission command to control a camera or antenna mount, using a quaternion as reference.
        DoGuidedMaster                             = 221,         //[Params 0: SystemID           | 1: ComponentID       ] set id of master controller
        DoGuidedLimits                             = 222,         //[Params 0: Timeout            | 1: MinAltitude        | 2: MaxAltitude        | 3: Horiz.MoveLimit   ] Set limits for external control
        DoEngineControl                            = 223,         //[Params 0: StartEngine        | 1: ColdStart          | 2: HeightDelay        | 3: Options           ] Control vehicle engine. This is interpreted by the vehicles engine controller to change the target engine state. It is intended for vehicles with internal combustion engines
        DoSetMissionCurrent                        = 224,         //[Params 0: Number             | 1: ResetMission      ] | Set the mission item with sequence number seq as the current item and emit MISSION_CURRENT (whether or not the mission number changed). | If a mission is currently being executed, the system will continue to this new mission item on the shortest path, skipping any intermediate mission items. | Note that mission jump repeat counters are not reset unless param2 is set (see MAV_CMD_DO_JUMP param2). | This command may trigger a mission state-machine change on some systems: for example from MISSION_STATE_NOT_STARTED or MISSION_STATE_PAUSED to MISSION_STATE_ACTIVE. | If the system is in mission mode, on those systems this command might therefore start, restart or resume the mission. | If the system is not in mission mode this command must not trigger a switch to mission mode. | The mission may be "reset" using param2. | Resetting sets jump counters to initial values (to reset counters without changing the current mission item set the param1 to `-1`). | Resetting also explicitly changes a mission state of MISSION_STATE_COMPLETE to MISSION_STATE_PAUSED or MISSION_STATE_ACTIVE, potentially allowing it to resume when it is (next) in a mission mode. | The command will ACK with MAV_RESULT_FAILED if the sequence number is out of range (including if there is no mission item).
        DoLast                                     = 240,         //NOP - This command is only used to mark the upper limit of the DO commands in the enumeration
        PreflightCalibration                       = 241,         //[Params 0: GyroTemperature    | 1: Magnetometer       | 2: GroundPressure     | 3: RemoteControl      | 4: Accelerometer      | 5: CompmotorAirspeed  | 6: ESCorBaro         ] Trigger calibration. This command will be only accepted if in pre-flight mode. Except for Temperature Calibration, only one sensor should be set in a single message and all others should be zero.
        PreflightSetSensorOffsets                  = 242,         //[Params 0: SensorType         | 1: XOffset            | 2: YOffset            | 3: ZOffset            | 4: 4thDimension       | 5: 5thDimension       | 6: 6thDimension      ] Set sensor offsets. This command will be only accepted if in pre-flight mode.
        PreflightUavcan                            = 243,         //[Params 0: ActuatorID        ] Trigger UAVCAN configuration (actuator ID assignment and direction mapping). Note that this maps to the legacy UAVCAN v0 function UAVCAN_ENUMERATE, which is intended to be executed just once during initial vehicle configuration (it is not a normal pre-flight command and has been poorly named).
        PreflightStorage                           = 245,         //[Params 0: ParameterStorage   | 1: MissionStorage     | 2: LoggingRate       ] Request storage of different parameter values and logs. This command will be only accepted if in pre-flight mode.
        PreflightRebootShutdown                    = 246,         //[Params 0: Autopilot          | 1: Companion          | 2: ComponentAction    | 3: ComponentID        | 5: Conditions        ] Request the reboot or shutdown of system components.
        OverrideGoto                               = 252,         //[Params 0: Continue           | 1: Position           | 2: Frame              | 3: Yaw                | 4: Latitude/X         | 5: Longitude/Y        | 6: Altitude/Z        ] Override current mission with command to pause mission, pause mission and move to position, continue/resume mission. When param 1 indicates that the mission is paused (MAV_GOTO_DO_HOLD), param 2 defines whether it holds in place or moves to another position.
        ObliqueSurvey                              = 260,         //[Params 0: Distance           | 1: Shutter            | 2: MinInterval        | 3: Positions          | 4: RollAngle          | 5: PitchAngle        ] Mission command to set a Camera Auto Mount Pivoting Oblique Survey (Replaces CAM_TRIGG_DIST for this purpose). The camera is triggered each time this distance is exceeded, then the mount moves to the next position. Params 4~6 set-up the angle limits and number of positions for oblique survey, where mount-enabled vehicles automatically roll the camera between shots to emulate an oblique camera setup (providing an increased HFOV). This command can also be used to set the shutter integration time for the camera.
        DoSetStandardMode                          = 262,         //[Params 0: StandardMode      ] Enable the specified standard MAVLink mode. | If the specified mode is not supported, the vehicle should ACK with MAV_RESULT_FAILED. | See https://mavlink.io/en/services/standard_modes.html
        MissionStart                               = 300,         //[Params 0: FirstItem          | 1: LastItem          ] start running a mission
        ActuatorTest                               = 310,         //[Params 0: Value              | 1: Timeout            | 4: OutputFunction    ] Actuator testing command. This is similar to MAV_CMD_DO_MOTOR_TEST but operates on the level of output functions, i.e. it is possible to test Motor1 independent from which output it is configured on. Autopilots must NACK this command with MAV_RESULT_TEMPORARILY_REJECTED while armed.
        ConfigureActuator                          = 311,         //[Params 0: Configuration      | 4: OutputFunction    ] Actuator configuration command.
        ComponentArmDisarm                         = 400,         //[Params 0: Arm                | 1: Force             ] Arms / Disarms a component
        RunPrearmChecks                            = 401,         //Instructs a target system to run pre-arm checks. | This allows preflight checks to be run on demand, which may be useful on systems that normally run them at low rate, or which do not trigger checks when the armable state might have changed. | This command should return MAV_RESULT_ACCEPTED if it will run the checks. | The results of the checks are usually then reported in SYS_STATUS messages (this is system-specific). | The command should return MAV_RESULT_TEMPORARILY_REJECTED if the system is already armed.
        IlluminatorOnOff                           = 405,         //[Params 0: Enable            ] Turns illuminators ON/OFF. An illuminator is a light source that is used for lighting up dark areas external to the system: e.g. a torch or searchlight (as opposed to a light source for illuminating the system itself, e.g. an indicator light).
        DoIlluminatorConfigure                     = 406,         //[Params 0: Mode               | 1: Brightness         | 2: StrobePeriod       | 3: StrobeDuty        ] Configures illuminator settings. An illuminator is a light source that is used for lighting up dark areas external to the system: e.g. a torch or searchlight (as opposed to a light source for illuminating the system itself, e.g. an indicator light).
        GetHomePosition                            = 410,         //Request the home position from the vehicle. | The vehicle will ACK the command and then emit the HOME_POSITION message.
        InjectFailure                              = 420,         //[Params 0: Failureunit        | 1: Failuretype        | 2: Instance          ] Inject artificial failure for testing purposes. Note that autopilots should implement an additional protection before accepting this command such as a specific param setting.
        StartRxPair                                = 500,         //[Params 0: RCType             | 1: RCSubType         ] Starts receiver pairing.
        GetMessageInterval                         = 510,         //[Params 0: MessageID         ] | Request the interval between messages for a particular MAVLink message ID. | The receiver should ACK the command and then emit its response in a MESSAGE_INTERVAL message.
        SetMessageInterval                         = 511,         //[Params 0: MessageID          | 1: Interval           | 2: ReqParam3          | 3: ReqParam4          | 4: ReqParam5          | 5: ReqParam6          | 6: ResponseTarget    ] Set the interval between messages for a particular MAVLink message ID. This interface replaces REQUEST_DATA_STREAM.
        RequestMessage                             = 512,         //[Params 0: MessageID          | 1: ReqParam1          | 2: ReqParam2          | 3: ReqParam3          | 4: ReqParam4          | 5: ReqParam5          | 6: ResponseTarget    ] Request the target system(s) emit a single instance of a specified message (i.e. a "one-shot" version of MAV_CMD_SET_MESSAGE_INTERVAL).
        RequestProtocolVersion                     = 519,         //[Params 0: Protocol          ] Request MAVLink protocol version compatibility. All receivers should ACK the command and then emit their capabilities in an PROTOCOL_VERSION message
        RequestAutopilotCapabilities               = 520,         //[Params 0: Version           ] Request autopilot capabilities. The receiver should ACK the command and then emit its capabilities in an AUTOPILOT_VERSION message
        RequestCameraInformation                   = 521,         //[Params 0: Capabilities      ] Request camera information (CAMERA_INFORMATION).
        RequestCameraSettings                      = 522,         //[Params 0: Settings          ] Request camera settings (CAMERA_SETTINGS).
        RequestStorageInformation                  = 525,         //[Params 0: StorageID          | 1: Information       ] Request storage information (STORAGE_INFORMATION). Use the command's target_component to target a specific component's storage.
        StorageFormat                              = 526,         //[Params 0: StorageID          | 1: Format             | 2: ResetImageLog     ] Format a storage medium. Once format is complete, a STORAGE_INFORMATION message is sent. Use the command's target_component to target a specific component's storage.
        RequestCameraCaptureStatus                 = 527,         //[Params 0: CaptureStatus     ] Request camera capture status (CAMERA_CAPTURE_STATUS)
        RequestFlightInformation                   = 528,         //[Params 0: FlightInformation ] Request flight information (FLIGHT_INFORMATION)
        ResetCameraSettings                        = 529,         //[Params 0: Reset              | 1: TargetCameraID    ] Reset all camera settings to Factory Default
        SetCameraMode                              = 530,         //[Params 0: id                 | 1: CameraMode        ] Set camera running mode. Use NaN for reserved values. GCS will send a MAV_CMD_REQUEST_VIDEO_STREAM_STATUS command after a mode change if the camera supports video streaming.
        SetCameraZoom                              = 531,         //[Params 0: ZoomType           | 1: ZoomValue          | 2: TargetCameraID    ] Set camera zoom. Camera must respond with a CAMERA_SETTINGS message (on success).
        SetCameraFocus                             = 532,         //[Params 0: FocusType          | 1: FocusValue         | 2: TargetCameraID    ] Set camera focus. Camera must respond with a CAMERA_SETTINGS message (on success).
        SetStorageUsage                            = 533,         //[Params 0: StorageID          | 1: Usage             ] Set that a particular storage is the preferred location for saving photos, videos, and/or other media (e.g. to set that an SD card is used for storing videos). | There can only be one preferred save location for each particular media type: setting a media usage flag will clear/reset that same flag if set on any other storage. | If no flag is set the system should use its default storage. | A target system can choose to always use default storage, in which case it should ACK the command with MAV_RESULT_UNSUPPORTED. | A target system can choose to not allow a particular storage to be set as preferred storage, in which case it should ACK the command with MAV_RESULT_DENIED.
        SetCameraSource                            = 534,         //[Params 0: deviceid           | 1: primarysource      | 2: secondarysource   ] Set camera source. Changes the camera's active sources on cameras with multiple image sensors.
        JumpTag                                    = 600,         //[Params 0: Tag               ] Tagged jump target. Can be jumped to with MAV_CMD_DO_JUMP_TAG.
        DoJumpTag                                  = 601,         //[Params 0: Tag                | 1: Repeat            ] Jump to the matching tag in the mission list. Repeat this action for the specified number of times. A mission should contain a single matching tag for each jump. If this is not the case then a jump to a missing tag should complete the mission, and a jump where there are multiple matching tags should always select the one with the lowest mission sequence number.
        DoGimbalManagerPitchyaw                    = 1000,        //[Params 0: Pitchangle         | 1: Yawangle           | 2: Pitchrate          | 3: Yawrate            | 4: Gimbalmanagerflags | 5: GimbaldeviceID    ] Set gimbal manager pitch/yaw setpoints (low rate command). It is possible to set combinations of the values below. E.g. an angle as well as a desired angular rate can be used to get to this angle at a certain angular rate, or an angular rate only will result in continuous turning. NaN is to be used to signal unset. Note: only the gimbal manager will react to this command - it will be ignored by a gimbal device. Use GIMBAL_MANAGER_SET_PITCHYAW if you need to stream pitch/yaw setpoints at higher rate.
        DoGimbalManagerConfigure                   = 1001,        //[Params 0: sysidprimarycontrol | 1: compidprimarycontrol | 2: sysidsecondarycontrol | 3: compidsecondarycontrol | 4: GimbaldeviceID    ] Gimbal configuration to set which sysid/compid is in primary and secondary control.
        ImageStartCapture                          = 2000,        //[Params 0: TargetCameraID     | 1: Interval           | 2: TotalImages        | 3: SequenceNumber    ] Start image capture sequence. CAMERA_IMAGE_CAPTURED must be emitted after each capture. | Param1 (id) may be used to specify the target camera: 0: all cameras, 1 to 6: autopilot-connected cameras, 7-255: MAVLink camera component ID. | It is needed in order to target specific cameras connected to the autopilot, or specific sensors in a multi-sensor camera (neither of which have a distinct MAVLink component ID). | It is also needed to specify the target camera in missions. | When used in a mission, an autopilot should execute the MAV_CMD for a specified local camera (param1 = 1-6), or resend it as a command if it is intended for a MAVLink camera (param1 = 7 - 255), setting the command's target_component as the param1 value (and setting param1 in the command to zero). | If the param1 is 0 the autopilot should do both. | When sent in a command the target MAVLink address is set using target_component. | If addressed specifically to an autopilot: param1 should be used in the same way as it is for missions (though command should NACK with MAV_RESULT_DENIED if a specified local camera does not exist). | If addressed to a MAVLink camera, param 1 can be used to address all cameras (0), or to separately address 1 to 7 individual sensors. Other values should be NACKed with MAV_RESULT_DENIED. | If the command is broadcast (target_component is 0) then param 1 should be set to 0 (any other value should be NACKED with MAV_RESULT_DENIED). An autopilot would trigger any local cameras and forward the command to all channels.
        ImageStopCapture                           = 2001,        //[Params 0: TargetCameraID    ] Stop image capture sequence. | Param1 (id) may be used to specify the target camera: 0: all cameras, 1 to 6: autopilot-connected cameras, 7-255: MAVLink camera component ID. | It is needed in order to target specific cameras connected to the autopilot, or specific sensors in a multi-sensor camera (neither of which have a distinct MAVLink component ID). | It is also needed to specify the target camera in missions. | When used in a mission, an autopilot should execute the MAV_CMD for a specified local camera (param1 = 1-6), or resend it as a command if it is intended for a MAVLink camera (param1 = 7 - 255), setting the command's target_component as the param1 value (and setting param1 in the command to zero). | If the param1 is 0 the autopilot should do both. | When sent in a command the target MAVLink address is set using target_component. | If addressed specifically to an autopilot: param1 should be used in the same way as it is for missions (though command should NACK with MAV_RESULT_DENIED if a specified local camera does not exist). | If addressed to a MAVLink camera, param1 can be used to address all cameras (0), or to separately address 1 to 7 individual sensors. Other values should be NACKed with MAV_RESULT_DENIED. | If the command is broadcast (target_component is 0) then param 1 should be set to 0 (any other value should be NACKED with MAV_RESULT_DENIED). An autopilot would trigger any local cameras and forward the command to all channels.
        RequestCameraImageCapture                  = 2002,        //[Params 0: Number            ] Re-request a CAMERA_IMAGE_CAPTURED message.
        DoTriggerControl                           = 2003,        //[Params 0: Enable             | 1: Reset              | 2: Pause              | 3: TargetCameraID    ] Enable or disable on-board camera triggering system.
        CameraTrackPoint                           = 2004,        //[Params 0: Pointx             | 1: Pointy             | 2: Radius             | 3: TargetCameraID    ] If the camera supports point visual tracking (CAMERA_CAP_FLAGS_HAS_TRACKING_POINT is set), this command allows to initiate the tracking.
        CameraTrackRectangle                       = 2005,        //[Params 0: Topleftcornerx     | 1: Topleftcornery     | 2: Bottomrightcornerx | 3: Bottomrightcornery | 4: TargetCameraID    ] If the camera supports rectangle visual tracking (CAMERA_CAP_FLAGS_HAS_TRACKING_RECTANGLE is set), this command allows to initiate the tracking.
        CameraStopTracking                         = 2010,        //[Params 0: TargetCameraID    ] Stops ongoing tracking.
        VideoStartCapture                          = 2500,        //[Params 0: StreamID           | 1: StatusFrequency    | 2: TargetCameraID    ] Starts video capture (recording).
        VideoStopCapture                           = 2501,        //[Params 0: StreamID           | 1: TargetCameraID    ] Stop the current video capture (recording).
        VideoStartStreaming                        = 2502,        //[Params 0: StreamID           | 1: TargetCameraID    ] Start video streaming
        VideoStopStreaming                         = 2503,        //[Params 0: StreamID           | 1: TargetCameraID    ] Stop the given video stream
        RequestVideoStreamInformation              = 2504,        //[Params 0: StreamID          ] Request video stream information (VIDEO_STREAM_INFORMATION)
        RequestVideoStreamStatus                   = 2505,        //[Params 0: StreamID          ] Request video stream status (VIDEO_STREAM_STATUS)
        LoggingStart                               = 2510,        //[Params 0: Format            ] Request to start streaming logging data over MAVLink (see also LOGGING_DATA message)
        LoggingStop                                = 2511,        //Request to stop streaming log data over MAVLink
        AirframeConfiguration                      = 2520,        //[Params 0: LandingGearID      | 1: LandingGearPosition]
        ControlHighLatency                         = 2600,        //[Params 0: Enable            ] Request to start/stop transmitting over the high latency telemetry
        PanoramaCreate                             = 2800,        //[Params 0: HorizontalAngle    | 1: VerticalAngle      | 2: HorizontalSpeed    | 3: VerticalSpeed     ] Create a panorama at the current position
        DoVtolTransition                           = 3000,        //[Params 0: State              | 1: Immediate         ] Request VTOL transition
        ArmAuthorizationRequest                    = 3001,        //[Params 0: SystemID          ] Request authorization to arm the vehicle to a external entity, the arm authorizer is responsible to request all data that is needs from the vehicle before authorize or deny the request. | If approved the COMMAND_ACK message progress field should be set with period of time that this authorization is valid in seconds. | If the authorization is denied COMMAND_ACK.result_param2 should be set with one of the reasons in ARM_AUTH_DENIED_REASON.
        SetGuidedSubmodeStandard                   = 4000,        //This command sets the submode to standard guided when vehicle is in guided mode. The vehicle holds position and altitude and the user can input the desired velocities along all three axes.
        SetGuidedSubmodeCircle                     = 4001,        //[Params 0: Radius             | 4: Latitude           | 5: Longitude         ] This command sets submode circle when vehicle is in guided mode. Vehicle flies along a circle facing the center of the circle. The user can input the velocity along the circle and change the radius. If no input is given the vehicle will hold position.
        ConditionGate                              = 4501,        //[Params 0: Geometry           | 1: UseAltitude        | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Delay mission state machine until gate has been reached.
        NavFenceReturnPoint                        = 5000,        //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] Fence return point (there can only be one such point in a geofence definition). If rally points are supported they should be used instead.
        NavFencePolygonVertexInclusion             = 5001,        //[Params 0: VertexCount        | 1: InclusionGroup     | 4: Latitude           | 5: Longitude         ] Fence vertex for an inclusion polygon (the polygon must not be self-intersecting). The vehicle must stay within this area. Minimum of 3 vertices required. | The vertices for a polygon must be sent sequentially, each with param1 set to the total number of vertices in the polygon.
        NavFencePolygonVertexExclusion             = 5002,        //[Params 0: VertexCount        | 4: Latitude           | 5: Longitude         ] Fence vertex for an exclusion polygon (the polygon must not be self-intersecting). The vehicle must stay outside this area. Minimum of 3 vertices required. | The vertices for a polygon must be sent sequentially, each with param1 set to the total number of vertices in the polygon.
        NavFenceCircleInclusion                    = 5003,        //[Params 0: Radius             | 1: InclusionGroup     | 4: Latitude           | 5: Longitude         ] Circular fence area. The vehicle must stay inside this area.
        NavFenceCircleExclusion                    = 5004,        //[Params 0: Radius             | 4: Latitude           | 5: Longitude         ] Circular fence area. The vehicle must stay outside this area.
        NavRallyPoint                              = 5100,        //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] Rally point. You can have multiple rally points defined.
        UavcanGetNodeInfo                          = 5200,        //Commands the vehicle to respond with a sequence of messages UAVCAN_NODE_INFO, one message per every UAVCAN node that is online. Note that some of the response messages can be lost, which the receiver can detect easily by checking whether every received UAVCAN_NODE_STATUS has a matching message UAVCAN_NODE_INFO received earlier; if not, this command should be sent again in order to request re-transmission of the node information messages.
        DoSetSafetySwitchState                     = 5300,        //[Params 0: DesiredState      ] Change state of safety switch.
        DoAdsbOutIdent                             = 10001,       //Trigger the start of an ADSB-out IDENT. This should only be used when requested to do so by an Air Traffic Controller in controlled airspace. This starts the IDENT which is then typically held for 18 seconds by the hardware per the Mode A, C, and S transponder spec.
        PayloadPrepareDeploy                       = 30001,       //[Params 0: OperationMode      | 1: ApproachVector     | 2: GroundSpeed        | 3: AltitudeClearance  | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Deploy payload on a Lat / Lon / Alt position. This includes the navigation to reach the required release position and velocity.
        PayloadControlDeploy                       = 30002,       //[Params 0: OperationMode     ] Control the payload deployment.
        WaypointUser1                              = 31000,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined waypoint item. Ground Station will show the Vehicle as flying through this item.
        WaypointUser2                              = 31001,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined waypoint item. Ground Station will show the Vehicle as flying through this item.
        WaypointUser3                              = 31002,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined waypoint item. Ground Station will show the Vehicle as flying through this item.
        WaypointUser4                              = 31003,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined waypoint item. Ground Station will show the Vehicle as flying through this item.
        WaypointUser5                              = 31004,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined waypoint item. Ground Station will show the Vehicle as flying through this item.
        SpatialUser1                               = 31005,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined spatial item. Ground Station will not show the Vehicle as flying through this item. Example: ROI item.
        SpatialUser2                               = 31006,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined spatial item. Ground Station will not show the Vehicle as flying through this item. Example: ROI item.
        SpatialUser3                               = 31007,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined spatial item. Ground Station will not show the Vehicle as flying through this item. Example: ROI item.
        SpatialUser4                               = 31008,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined spatial item. Ground Station will not show the Vehicle as flying through this item. Example: ROI item.
        SpatialUser5                               = 31009,       //[Params 4: Latitude           | 5: Longitude          | 6: Altitude          ] User defined spatial item. Ground Station will not show the Vehicle as flying through this item. Example: ROI item.
        User1                                      = 31010,       //User defined command. Ground Station will not show the Vehicle as flying through this item. Example: MAV_CMD_DO_SET_PARAMETER item.
        User2                                      = 31011,       //User defined command. Ground Station will not show the Vehicle as flying through this item. Example: MAV_CMD_DO_SET_PARAMETER item.
        User3                                      = 31012,       //User defined command. Ground Station will not show the Vehicle as flying through this item. Example: MAV_CMD_DO_SET_PARAMETER item.
        User4                                      = 31013,       //User defined command. Ground Station will not show the Vehicle as flying through this item. Example: MAV_CMD_DO_SET_PARAMETER item.
        User5                                      = 31014,       //User defined command. Ground Station will not show the Vehicle as flying through this item. Example: MAV_CMD_DO_SET_PARAMETER item.
        CanForward                                 = 32000,       //[Params 0: bus               ] Request forwarding of CAN packets from the given CAN bus to this component. CAN Frames are sent using CAN_FRAME and CANFD_FRAME messages
        FixedMagCalYaw                             = 42006,       //[Params 0: Yaw                | 1: CompassMask        | 2: Latitude           | 3: Longitude         ] Magnetometer calibration based on provided known yaw. This allows for fast calibration using WMM field tables in the vehicle, given only the known yaw of the vehicle. If Latitude and longitude are both zero then use the current vehicle location.
        DoWinch                                    = 42600,       //[Params 0: Instance           | 1: Action             | 2: Length             | 3: Rate              ] Command to operate winch.
        ExternalPositionEstimate                   = 43003        //[Params 0: transmission_time  | 1: processing_time    | 2: accuracy           | 4: Latitude           | 5: Longitude          | 6: Altitude          ] Provide an external position estimate for use when dead-reckoning. This is meant to be used for occasional position resets that may be provided by a external system such as a remote pilot using landmarks over a video link.
    }

